-- 外研社八上 wy8A 词表灌库(junior_vocab)· publisher=junior_fltrp · volume=wy8A · grade=8 · 256词/6单元
-- 短语 pos/phonetic=NULL · freq_rank=课本顺序 · IPA照抄视觉读出 · ★DELETE 带 publisher+volume 绝不动人教/其他册★
BEGIN;
DELETE FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy8A';

-- 断言
DO $$
DECLARE tot int; c int; poll int; nulls int; dup int;
BEGIN
  SELECT count(*) INTO tot FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy8A';
  IF tot<>256 THEN RAISE EXCEPTION 'total=% 期望256', tot; END IF;
  SELECT count(*) INTO c FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy8A' AND unit='U1'; IF c<>51 THEN RAISE EXCEPTION 'U1=% 期望51', c; END IF;
  SELECT count(*) INTO c FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy8A' AND unit='U2'; IF c<>46 THEN RAISE EXCEPTION 'U2=% 期望46', c; END IF;
  SELECT count(*) INTO c FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy8A' AND unit='U3'; IF c<>45 THEN RAISE EXCEPTION 'U3=% 期望45', c; END IF;
  SELECT count(*) INTO c FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy8A' AND unit='U4'; IF c<>31 THEN RAISE EXCEPTION 'U4=% 期望31', c; END IF;
  SELECT count(*) INTO c FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy8A' AND unit='U5'; IF c<>44 THEN RAISE EXCEPTION 'U5=% 期望44', c; END IF;
  SELECT count(*) INTO c FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy8A' AND unit='U6'; IF c<>39 THEN RAISE EXCEPTION 'U6=% 期望39', c; END IF;
  SELECT count(*) INTO poll FROM public.junior_vocab WHERE volume='wy8A' AND publisher<>'junior_fltrp';
  IF poll<>0 THEN RAISE EXCEPTION 'polluted=%', poll; END IF;
  SELECT count(*) INTO nulls FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy8A' AND (word IS NULL OR meaning_cn IS NULL);
  IF nulls<>0 THEN RAISE EXCEPTION 'word/meaning空=%', nulls; END IF;
  SELECT count(*) INTO dup FROM (SELECT word_id FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy8A' GROUP BY word_id HAVING count(*)>1) t;
  IF dup<>0 THEN RAISE EXCEPTION 'word_id重复=%', dup; END IF;
  RAISE NOTICE 'OK: wy8A 词表 % 条 · 六单元计数达标', tot;
END $$;

COMMIT;
SELECT unit, count(*) FROM public.junior_vocab WHERE publisher='junior_fltrp' AND volume='wy8A' GROUP BY unit ORDER BY min(freq_rank);